"""ISO-8601 durations: parsing, calendar addition and canonical output.

See task.md. `Duration` and `DurationError` are part of the contract: keep their
names, fields and field order as they are.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime


class DurationError(ValueError):
    """Raised for text that is not a well-formed ISO-8601 duration."""


@dataclass(frozen=True)
class Duration:
    """A duration. Every component is non-negative; `negative` signs the whole."""

    years: int = 0
    months: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: int = 0
    microseconds: int = 0
    negative: bool = False


import re
import calendar
from datetime import timedelta
from fractions import Fraction

_N = r"([0-9]+(?:[.,][0-9]+)?)"
_RE = re.compile(
    rf"(-)?P(?:{_N}W|(?:{_N}Y)?(?:{_N}M)?(?:{_N}D)?(T(?:{_N}H)?(?:{_N}M)?(?:{_N}S)?)?)"
)

_US = {"D": 86_400_000_000, "H": 3_600_000_000, "M": 60_000_000, "S": 1_000_000}


def parse(text: str) -> Duration:
    """Parse an ISO-8601 duration."""
    if not isinstance(text, str):
        raise DurationError("duration must be a string")
    m = _RE.fullmatch(text)
    if m is None:
        raise DurationError(f"invalid duration: {text!r}")
    neg, week, y, mo, d, t, h, mi, s = m.groups()
    if t == "T":
        raise DurationError("'T' with no time component")
    if week is None and all(g is None for g in (y, mo, d, h, mi, s)):
        raise DurationError("no components")

    if week is not None:
        items = [("W", week)]
    else:
        items = [(k, v) for k, v in
                 (("Y", y), ("M", mo), ("D", d), ("H", h), ("m", mi), ("S", s))
                 if v is not None]

    try:
        values = {}
        frac = None
        for i, (key, raw) in enumerate(items):
            raw = raw.replace(",", ".")
            if "." in raw:
                if i != len(items) - 1 or key in ("Y", "M"):
                    raise DurationError(f"invalid fraction in {text!r}")
                frac = (key, Fraction(raw))
            else:
                values[key] = int(raw)
    except ValueError as e:
        if isinstance(e, DurationError):
            raise
        raise DurationError(f"invalid number in {text!r}") from e

    years = values.get("Y", 0)
    months = values.get("M", 0)
    days = values.get("D", 0) + 7 * values.get("W", 0)
    hours = values.get("H", 0)
    minutes = values.get("m", 0)
    seconds = values.get("S", 0)
    micro = 0

    if frac is not None:
        key, f = frac
        whole = int(f)
        rest = f - whole
        if key == "W":
            days += 7 * whole
            rest *= 7
            unit = "D"
        else:
            unit = {"m": "M"}.get(key, key)
            # whole part of a fractional component
            if key == "D":
                days += whole
            elif key == "H":
                hours += whole
            elif key == "m":
                minutes += whole
            else:
                seconds += whole
        if key == "W":
            whole_days = int(rest)
            days += whole_days
            rest -= whole_days
        total = int(rest * _US[unit])  # truncates towards zero
        for u in "DHMS":
            if _US[u] > _US[unit]:
                continue
            q, total = divmod(total, _US[u])
            if u == "D":
                days += q
            elif u == "H":
                hours += q
            elif u == "M":
                minutes += q
            else:
                seconds += q
        micro = total

    result = Duration(years, months, days, hours, minutes, seconds, micro, False)
    if neg and any((years, months, days, hours, minutes, seconds, micro)):
        result = Duration(years, months, days, hours, minutes, seconds, micro, True)
    return result


def add(start: datetime, duration: Duration) -> datetime:
    """Return `start` shifted by `duration`, calendar-correct."""
    sign = -1 if duration.negative else 1
    idx = start.year * 12 + (start.month - 1) + sign * (12 * duration.years + duration.months)
    year, month0 = divmod(idx, 12)
    month = month0 + 1
    if not 1 <= year <= 9999:
        raise ValueError("year out of range")
    day = min(start.day, calendar.monthrange(year, month)[1])
    shifted = start.replace(year=year, month=month, day=day)
    try:
        delta = timedelta(
            days=duration.days,
            hours=duration.hours,
            minutes=duration.minutes,
            seconds=duration.seconds,
            microseconds=duration.microseconds,
        )
        return shifted + sign * delta
    except OverflowError as e:
        raise ValueError(str(e)) from e


def format(duration: Duration) -> str:  # noqa: A001 - the contract names it this
    """Return the canonical ISO-8601 text for `duration`."""
    d = duration
    if not any((d.years, d.months, d.days, d.hours, d.minutes, d.seconds, d.microseconds)):
        return "PT0S"
    out = "-P" if d.negative else "P"
    if d.years:
        out += f"{d.years}Y"
    if d.months:
        out += f"{d.months}M"
    if d.days:
        out += f"{d.days}D"
    if d.hours or d.minutes or d.seconds or d.microseconds:
        out += "T"
        if d.hours:
            out += f"{d.hours}H"
        if d.minutes:
            out += f"{d.minutes}M"
        if d.seconds or d.microseconds:
            if d.microseconds:
                frac = f"{d.microseconds:06d}".rstrip("0")
                out += f"{d.seconds}.{frac}S"
            else:
                out += f"{d.seconds}S"
    return out
